// PRIDA 0.42 cumulative source + model update. No network writes or credential reads.
import fs from 'node:fs';
import path from 'node:path';
import {gunzipSync} from 'node:zlib';
import {spawnSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
export const RELEASE='0.42.0';
const STATE='.prida-0.42', PAYLOAD_SHA256="1c7b2d31c08f51949014f1f7515cf8a968373d5d24f11ece4287df2c9d1d2591", PAYLOAD_B64="";
const UNIT=["tests/architecture-029.test.mjs", "tests/doors-029.test.mjs", "tests/vehicle-030.test.mjs", "tests/asset-030.test.mjs", "tests/structures-030.test.mjs", "tests/vehicle-031.test.mjs", "tests/ram-flight-031.test.mjs", "tests/world-031.test.mjs", "tests/runway-0311.test.mjs", "tests/vehicle-0312.test.mjs", "tests/rockets-032.test.mjs", "tests/interiors-033.test.mjs", "tests/lifts-033.test.mjs", "tests/developer-ram-033.test.mjs", "tests/architecture-034.test.mjs", "tests/landscape-034.test.mjs", "tests/portal-035.test.mjs", "tests/portal-packaging-035.test.mjs", "tests/asset-bootstrap-0351.test.mjs", "tests/air-defence-036.test.mjs", "tests/performance-036.test.mjs", "tests/export-full-036.test.mjs", "tests/activity-037.test.mjs", "tests/armour-salvo-037.test.mjs", "tests/entity-delta-037.test.mjs", "tests/mobility-038.test.mjs", "tests/technology-040.test.mjs", "tests/characters-041.test.mjs", "tests/build-entrypoints.test.mjs", "tests/animations-042.test.mjs"];
const INTEGRATION=["tests/integration-030.test.mjs", "tests/integration-031.test.mjs", "tests/integration-contact-0312.test.mjs", "tests/integration-rockets-032.test.mjs", "tests/integration-world-031.test.mjs", "tests/integration-mobility-038.test.mjs", "tests/rapier-mobility-038.test.mjs", "tests/integration-interiors-033.test.mjs", "tests/integration-frontier-037.test.mjs", "tests/integration-air-defence-036.test.mjs", "tests/integration-041.test.mjs", "tests/gameplay-042.test.mjs"];
const defaultRoot=path.dirname(fileURLToPath(import.meta.url));
const hash=bytes=>createHash('sha256').update(bytes).digest('hex');
const ROOT_FILES=['index.html','server.mjs','accounts.mjs','package.json','package-lock.json','vite.config.js','Dockerfile','lobby-stage.js','lobby-ui.js','prida-update.mjs'];
const DIRECTORIES=['src','public','scripts','tests'];
const omitted=n=>n.startsWith('.')||['node_modules','dist','dist-crazygames','release','data'].includes(n)||/\.(env|db|sqlite|pem|key|zip|ttf|otf|woff2?)$/i.test(n);
export function safeName(name){
  if(typeof name!=='string'||name.startsWith('/')||name.includes('\\')||name.includes('\0')||name.includes(':')||name.split('/').some(p=>!p||p==='.'||p==='..'))throw Error('Unsafe update path: '+name);
  return name;
}
export function decodeEntry(value,name='entry'){
  if(typeof value==='string')return Buffer.from(value,'utf8');
  if(!value||value.encoding!=='base64'||typeof value.data!=='string'||!/^[a-f0-9]{64}$/.test(value.sha256))throw Error('Invalid binary entry: '+name);
  const bytes=Buffer.from(value.data,'base64');
  if(bytes.toString('base64')!==value.data||hash(bytes)!==value.sha256)throw Error('Binary checksum failed: '+name);
  return bytes;
}
export function decodePayload(){
  const raw=gunzipSync(Buffer.from(PAYLOAD_B64,'base64'),{maxOutputLength:64*1024*1024});
  if(hash(raw)!==PAYLOAD_SHA256)throw Error('Embedded payload checksum failed');
  const obj=JSON.parse(raw),result=new Map();
  for(const[name,value]of Object.entries(obj)){safeName(name);result.set(name,decodeEntry(value,name));}
  for(const n of ['index.html','src/simulation.js','src/entity-delta.js','src/custom-characters.js','src/base-drones.js','public/models/tactical-player.glb','public/models/aegis-player.glb','public/models/aegis-gauntlets.glb','tests/integration-041.test.mjs','src/aircraft-geometry.js','src/aircraft-contact.js','src/aircraft-physics.js','src/aircraft-debris.js','src/fpv-inventory.js','src/suit-weapons.js','public/animations/uploaded-042.json','public/models/fpv.glb','public/icons/fpv.png','tests/gameplay-042.test.mjs'])if(!result.has(n))throw Error('Incomplete update: '+n);
  if(JSON.parse(result.get('package.json')).version!==RELEASE)throw Error('Package version does not match installer');
  return result;
}
function assertRegularParents(root,name){
  let p=root;
  for(const part of name.split('/')){p=path.join(p,part);if(fs.existsSync(p)&&fs.lstatSync(p).isSymbolicLink())throw Error('Refusing update through a symlink: '+name);}
}
function apply(root,files){
  for(const[name,bytes]of files){assertRegularParents(root,name);const p=path.join(root,name);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,bytes);}
}
function copyTree(from,to){
  fs.mkdirSync(to,{recursive:true});
  for(const e of fs.readdirSync(from,{withFileTypes:true})){
    if(omitted(e.name))continue;
    if(e.isSymbolicLink())throw Error('Unexpected source symlink: '+path.join(from,e.name));
    const a=path.join(from,e.name),b=path.join(to,e.name);
    if(e.isDirectory())copyTree(a,b);else if(e.isFile())fs.copyFileSync(a,b);
  }
}
function stagedCopy(root,stage){
  fs.mkdirSync(stage,{recursive:true});
  for(const n of ROOT_FILES){const p=path.join(root,n);if(fs.existsSync(p)){assertRegularParents(root,n);fs.copyFileSync(p,path.join(stage,n));}}
  for(const n of DIRECTORIES){const p=path.join(root,n);if(fs.existsSync(p)){assertRegularParents(root,n);copyTree(p,path.join(stage,n));}}
}
function run(stage,args,label,env={}){
  console.log('[PRIDA '+RELEASE+'] '+label);
  const r=spawnSync(process.execPath,args,{cwd:stage,stdio:'inherit',env:{...process.env,...env},timeout:360000});
  if(r.error||r.status!==0)throw Error(label+' failed. No prepared game files installed. '+(r.error?.message||'exit '+r.status));
}
function vite(root,stage,out,env={}){
  const bin=path.join(root,'node_modules/vite/bin/vite.js');
  if(!fs.existsSync(bin))throw Error('Vite missing. Run npm ci before installation.');
  run(stage,[bin,'build','--base','./','--outDir',out,'--emptyOutDir'],out+' Vite build',env);
}
function matches(root,files){
  for(const[n,b]of files){const p=path.join(root,n);if(!fs.existsSync(p)||!fs.lstatSync(p).isFile()||!fs.readFileSync(p).equals(b))return false;}
  return true;
}
function currentBytes(root,files){const m=new Map();for(const[n]of files){assertRegularParents(root,n);const p=path.join(root,n);m.set(n,fs.existsSync(p)?fs.readFileSync(p):null);}return m;}
function sameOriginals(root,originals){for(const[n,b]of originals){const p=path.join(root,n),now=fs.existsSync(p)?fs.readFileSync(p):null;if((b===null)!==(now===null)||(b&&now&&!b.equals(now)))throw Error('Concurrent source edit detected; no commit: '+n);}}
export function commitFiles(root,files,stateDir,originals=currentBytes(root,files)){
  sameOriginals(root,originals);
  const prepared=path.join(stateDir,'commit'),backup=path.join(stateDir,'backup');
  fs.mkdirSync(backup,{recursive:true});apply(prepared,files);
  for(const[n,b]of originals)if(b!==null){const p=path.join(backup,n);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,b);}
  const done=[];
  try{
    for(const[n]of files){assertRegularParents(root,n);const p=path.join(root,n);fs.mkdirSync(path.dirname(p),{recursive:true});fs.renameSync(path.join(prepared,n),p);done.push(n);}
  }catch(error){
    const restoreErrors=[];
    for(const n of done.reverse())try{const b=originals.get(n),p=path.join(root,n);if(b===null)fs.rmSync(p,{force:true});else fs.writeFileSync(p,b);}catch(e){restoreErrors.push(n+': '+e.message);}
    if(restoreErrors.length)throw new AggregateError([error,...restoreErrors.map(e=>new Error(e))],'Commit failed. Restore files from '+backup);
    throw error;
  }
}
export function install({checkOnly=false,root=defaultRoot}={}){
  root=path.resolve(root);const files=decodePayload(),stateDir=path.join(root,STATE),stage=path.join(stateDir,'staging');
  if(!checkOnly&&matches(root,files)){console.log('[PRIDA '+RELEASE+'] ALREADY INSTALLED; every payload byte matches.');return {status:'already-installed',files:files.size};}
  const originals=currentBytes(root,files);
  fs.mkdirSync(stateDir,{recursive:true});fs.rmSync(stage,{recursive:true,force:true});fs.rmSync(path.join(stateDir,'commit'),{recursive:true,force:true});
  stagedCopy(root,stage);apply(stage,files);
  console.log('[PRIDA '+RELEASE+'] '+files.size+' source/model entries staged. Supplied avatar meshes are local GLBs.');
  run(stage,['--test','--test-concurrency=1',...UNIT],'cumulative unit/regression gate');
  run(stage,['--test','--test-concurrency=1',...INTEGRATION],'actual Rapier / Three / full Arena gate');
  vite(root,stage,'.bundle-check');
  vite(root,stage,'.portal-basic-check',{VITE_CG_PORTAL:'1',VITE_CG_ADS:'basic'});
  vite(root,stage,'.portal-full-check',{VITE_CG_PORTAL:'1',VITE_CG_ADS:'full'});
  if(!checkOnly){commitFiles(root,files,stateDir,originals);fs.writeFileSync(path.join(stateDir,'installed.json'),JSON.stringify({version:RELEASE,payloadSHA256:PAYLOAD_SHA256,files:files.size},null,2));}
  fs.rmSync(stage,{recursive:true,force:true});fs.rmSync(path.join(stateDir,'commit'),{recursive:true,force:true});
  console.log('[PRIDA '+RELEASE+'] '+(checkOnly?'VERIFIED':'INSTALLED')+' — FPV ITEMS / FLIGHT / MOTIONS');
  return {status:checkOnly?'verified':'installed',files:files.size};
}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){
  try{install({checkOnly:process.argv.includes('--check')});}catch(e){console.error('[PRIDA '+RELEASE+'] '+(e.stack||e));process.exitCode=1;}
}
